<script setup lang="ts">
// API explorer: the OpenAPI 3.1 document of /api/v1 (GET /openapi.json, generated by the server from
// its own route table), routes by tag, schemas, a "try it" that sends the request with your session,
// and a curl command for scripts (Bearer token). docs/api.md has the prose.
import { computed, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import Icon from '@/components/icons/Icon.vue'
import Callout from '@/components/Callout.vue'
import CodeBlock from '@/components/CodeBlock.vue'
import Spinner from '@/components/Spinner.vue'
import EmptyState from '@/components/EmptyState.vue'
import SchemaTree from '@/components/apidocs/SchemaTree.vue'
import { useResource } from '@/api/cache'
import { request, ApiError } from '@/api/client'
import { curlFor, endpoints, example, gap, type Endpoint } from '@/api/sections/gapcore'
import { downloadText } from '@/composables/useClipboard'
import { atLeast } from '@/api/perms'
import { session } from '@/stores/session'
import { repos } from '@/stores/repos'

const doc = useResource(() => 'openapi', (s) => gap.openapi(s), { ttl: 300_000 })
const all = computed(() => (doc.data.value ? endpoints(doc.data.value) : []))
const q = ref('')
const filtered = computed(() => {
  const t = q.value.trim().toLowerCase()
  return t ? all.value.filter((e) => `${e.method} ${e.path} ${e.op.summary} ${e.op.tags.join(' ')} ${e.op['x-role']}`.toLowerCase().includes(t)) : all.value
})
const byTag = computed(() => {
  const m = new Map<string, Endpoint[]>()
  for (const e of filtered.value) {
    const t = e.op.tags[0] ?? 'Other'
    if (!m.has(t)) m.set(t, [])
    m.get(t)!.push(e)
  }
  return [...m.entries()].sort((a, b) => a[0].localeCompare(b[0]))
})

const route = useRoute()
const router = useRouter()
const selKey = computed(() => (typeof route.query.op === 'string' ? route.query.op : ''))
const sel = computed(() => all.value.find((e) => e.op.operationId === selKey.value) ?? all.value[0] ?? null)
function pick(e: Endpoint) { void router.replace({ query: { ...route.query, op: e.op.operationId } }) }

// ---- try it
const pathVals = ref<Record<string, string>>({})
const queryVals = ref<Record<string, string>>({})
const body = ref('')
const sending = ref(false)
const confirmWrite = ref(false)
const result = ref<{ status: number; ms: number; text: string; error?: boolean } | null>(null)
watch(sel, (e) => {
  result.value = null
  confirmWrite.value = false
  pathVals.value = {}
  queryVals.value = {}
  for (const p of e?.op.parameters ?? []) {
    if (p.in === 'path') pathVals.value[p.name] = p.name === 'name' && e!.path.includes('/repositories/') ? repos.current : ''
    if (p.in === 'query') queryVals.value[p.name] = p.name === 'repository' ? repos.current : ''
  }
  const schema = e?.op.requestBody?.content['application/json']?.schema
  body.value = schema && doc.data.value ? JSON.stringify(example(doc.data.value, schema), null, 2) : ''
}, { immediate: true })

const resolvedPath = computed(() => (sel.value ? sel.value.path.replace(/\{([a-z_]+)\}/g, (_, n: string) => encodeURIComponent(pathVals.value[n] ?? '')) : ''))
const unsafe = computed(() => !!sel.value && sel.value.method !== 'GET')
const binary = computed(() => !!sel.value && Object.values(sel.value.op.responses).some((r) => r.content && 'application/octet-stream' in r.content))
const sse = computed(() => !!sel.value && Object.values(sel.value.op.responses).some((r) => r.content && 'text/event-stream' in r.content))
const allowed = computed(() => !!sel.value && (sel.value.op.security?.length === 0 || atLeast(session.role, sel.value.op['x-role'])))
const missingPath = computed(() => Object.entries(pathVals.value).filter(([, v]) => !v.trim()).map(([k]) => k))
const curl = computed(() => (sel.value ? curlFor(window.location.origin, sel.value.method, resolvedPath.value, queryVals.value, unsafe.value ? body.value : '') : ''))

async function send() {
  const e = sel.value
  if (!e) return
  let parsed: unknown
  if (body.value.trim() && e.op.requestBody) {
    try { parsed = JSON.parse(body.value) } catch (x) { result.value = { status: 0, ms: 0, text: `The body is not valid JSON: ${(x as Error).message}`, error: true }; return }
  }
  sending.value = true
  const t0 = performance.now()
  try {
    const qs: Record<string, string> = {}
    for (const [k, v] of Object.entries(queryVals.value)) if (v) qs[k] = v
    const out = await request<unknown>(e.method, resolvedPath.value.replace(/^\/api\/v1/, ''), { query: qs, body: parsed, raw: binary.value, noAuthRedirect: true })
    const ms = Math.round(performance.now() - t0)
    let text = out === undefined ? '(no content)' : out instanceof ArrayBuffer ? `${out.byteLength} bytes of ciphertext` : JSON.stringify(out, null, 2)
    if (text.length > 200_000) text = text.slice(0, 200_000) + '\n… (cut at 200 KB)'
    result.value = { status: out === undefined ? 204 : 200, ms, text }
  } catch (x) {
    const ms = Math.round(performance.now() - t0)
    result.value = x instanceof ApiError ? { status: x.status, ms, text: JSON.stringify(x.body ?? { error: x.message }, null, 2), error: true } : { status: 0, ms, text: String(x), error: true }
  } finally {
    sending.value = false
  }
}
function download() { if (doc.data.value) downloadText('incus-backup-openapi.json', JSON.stringify(doc.data.value, null, 2), 'application/json') }
/** **bold** and `code` of the server's descriptions, after escaping everything else. */
function mdLite(t: string): string {
  const esc = t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
  return esc.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>').replace(/`([^`]+)`/g, '<code>$1</code>')
}
const methodClass = (m: string) => `m-${m.toLowerCase()}`
const successCode = computed(() => (sel.value ? Object.keys(sel.value.op.responses).find((c) => c.startsWith('2')) ?? '200' : ''))
const successSchema = computed(() => sel.value?.op.responses[successCode.value]?.content?.['application/json']?.schema)
const errorCodes = computed(() => (sel.value ? Object.entries(sel.value.op.responses).filter(([c]) => !c.startsWith('2')) : []))
</script>

<template>
  <div>
    <header class="page-head">
      <div>
        <h1>API</h1>
        <p class="lede">Every route of the management API with its role, parameters and JSON shapes. Try a call with your own session, or copy it as curl for a script.</p>
      </div>
      <div class="actions">
        <a class="btn" href="/api/v1/openapi.json" target="_blank" rel="noopener"><Icon name="external-link" :size="14" />openapi.json</a>
        <button type="button" class="btn" :disabled="!doc.data.value" @click="download"><Icon name="download" :size="14" />Download</button>
      </div>
    </header>

    <Callout v-if="doc.error.value" status="critical" title="Could not load the API description" :retry="doc.refresh">{{ doc.error.value.message }}</Callout>
    <p v-else-if="doc.loading.value" class="muted"><Spinner :size="13" /> Loading the API description…</p>

    <div v-else-if="doc.data.value" class="layout">
      <nav class="side panel" aria-label="Routes">
        <div class="search"><Icon name="search" :size="14" /><input v-model="q" class="input" type="search" placeholder="Filter routes (path, tag, role)" data-testid="api-filter" /></div>
        <p class="muted small count">{{ filtered.length }} of {{ all.length }} routes · API {{ doc.data.value.info.version }}</p>
        <div class="groups">
          <section v-for="[tag, eps] in byTag" :key="tag">
            <h3>{{ tag }}</h3>
            <button v-for="e in eps" :key="e.op.operationId" type="button" class="ep" :class="{ on: sel?.op.operationId === e.op.operationId }" :data-testid="`api-op-${e.op.operationId}`" @click="pick(e)">
              <span class="m" :class="methodClass(e.method)">{{ e.method }}</span><span class="p">{{ e.path.replace('/api/v1', '') }}</span>
            </button>
          </section>
          <EmptyState v-if="!filtered.length" title="No route matches" compact />
        </div>
      </nav>

      <article v-if="sel" class="detail" data-testid="api-detail">
        <section class="panel">
          <div class="panel-body">
            <p class="sig"><span class="m" :class="methodClass(sel.method)">{{ sel.method }}</span> <code>{{ sel.path }}</code></p>
            <h2 class="sum">{{ sel.op.summary }}</h2>
            <p class="meta">
              <span class="tag">role: <strong>{{ sel.op['x-role'] }}</strong></span>
              <span class="tag">repository: {{ sel.op['x-repository-binding'] }}</span>
              <span v-if="sel.op.security?.length === 0" class="tag">no login</span>
            </p>
            <p class="muted small" v-html="mdLite(sel.op.description ?? '')" />
          </div>
        </section>

        <section v-if="sel.op.parameters?.length" class="panel">
          <div class="panel-head"><h3>Parameters</h3></div>
          <table class="params">
            <thead><tr><th>Name</th><th>In</th><th>Type</th><th>Description</th></tr></thead>
            <tbody><tr v-for="p in sel.op.parameters" :key="p.in + p.name"><td><code>{{ p.name }}</code><span v-if="p.required" class="req">required</span></td><td>{{ p.in }}</td><td><code>{{ p.schema?.type }}</code></td><td>{{ p.description }}</td></tr></tbody>
          </table>
        </section>

        <div class="two">
          <section v-if="sel.op.requestBody" class="panel">
            <div class="panel-head"><h3>Request body</h3></div>
            <div class="panel-body"><SchemaTree :doc="doc.data.value" :schema="sel.op.requestBody.content['application/json']?.schema" /></div>
          </section>
          <section class="panel">
            <div class="panel-head"><h3>Response {{ successCode }}</h3></div>
            <div class="panel-body">
              <SchemaTree v-if="successSchema" :doc="doc.data.value" :schema="successSchema" />
              <p v-else class="muted small">{{ sel.op.responses[successCode]?.description }}</p>
              <details class="errs"><summary class="small">Error responses</summary><ul><li v-for="[c, r] in errorCodes" :key="c"><code>{{ c }}</code> {{ r.description }} <span class="muted">— <code>{"error": "..."}</code></span></li></ul></details>
            </div>
          </section>
        </div>

        <section class="panel try" data-testid="api-try">
          <div class="panel-head"><h3>Try it</h3><span class="muted small">Sent with your session ({{ session.name }}, {{ session.role || 'no role' }}).</span></div>
          <div class="panel-body form">
            <div v-for="(_, k) in pathVals" :key="'p' + k" class="row"><label :for="`pv-${k}`"><code>{{ k }}</code></label><input :id="`pv-${k}`" v-model="pathVals[k]" class="input mono" /></div>
            <div v-for="(_, k) in queryVals" :key="'q' + k" class="row"><label :for="`qv-${k}`"><code>?{{ k }}</code></label><input :id="`qv-${k}`" v-model="queryVals[k]" class="input mono" /></div>
            <div v-if="sel.op.requestBody" class="row col"><label for="api-body">Body (JSON)</label><textarea id="api-body" v-model="body" class="input mono body" rows="8" spellcheck="false" data-testid="api-body" /></div>
            <Callout v-if="sse" status="info">This is a live event stream; open it with EventSource. The console already listens to it.</Callout>
            <Callout v-else-if="!allowed" status="warn">Your role does not allow this route; the server would answer 403.</Callout>
            <label v-if="unsafe && !sse" class="confirm"><input v-model="confirmWrite" type="checkbox" data-testid="api-confirm" /> This {{ sel.method }} changes data on the server. Send it anyway.</label>
            <div class="sendrow">
              <button type="button" class="btn btn-primary" :disabled="sending || sse || missingPath.length > 0 || (unsafe && !confirmWrite)" data-testid="api-send" @click="send"><Spinner v-if="sending" :size="13" /><Icon v-else name="play" :size="14" />Send</button>
              <span v-if="missingPath.length" class="muted small">Fill in {{ missingPath.join(', ') }}.</span>
            </div>
            <div v-if="result" class="result" data-testid="api-result">
              <p class="small"><strong :class="result.error ? 'bad' : 'good'">{{ result.status || 'no answer' }}</strong> · {{ result.ms }} ms</p>
              <pre class="out">{{ result.text }}</pre>
            </div>
          </div>
        </section>

        <section class="panel">
          <div class="panel-head"><h3>curl</h3><span class="muted small">Create a token in your profile and export it as IB_TOKEN.</span></div>
          <div class="panel-body"><CodeBlock :code="curl" label="curl" /></div>
        </section>
      </article>
    </div>
  </div>
</template>

<style scoped>
.layout { display: grid; grid-template-columns: 340px minmax(0, 1fr); gap: 16px; align-items: start; }
.side { position: sticky; top: 12px; max-height: calc(100vh - 120px); display: flex; flex-direction: column; overflow: hidden; }
.search { display: flex; gap: 6px; align-items: center; padding: 10px 10px 4px; }
.search .input { flex: 1; }
.count { padding: 0 12px 6px; margin: 0; }
.groups { overflow: auto; padding: 0 6px 10px; }
.groups h3 { font-size: var(--fs-xs); text-transform: uppercase; letter-spacing: 0.06em; color: var(--text-muted); margin: 12px 6px 4px; }
.ep { display: flex; gap: 8px; align-items: center; width: 100%; border: 0; background: none; text-align: left; padding: 5px 6px; border-radius: var(--r-sm); cursor: pointer; font: inherit; color: var(--text); }
.ep:hover { background: var(--surface-3); }
.ep.on { background: var(--accent-soft); }
.ep .p { font-family: var(--font-mono); font-size: var(--fs-sm); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.m { display: inline-block; min-width: 52px; text-align: center; font-family: var(--font-mono); font-size: var(--fs-xs); font-weight: var(--fw-medium); border-radius: var(--r-sm); padding: 1px 4px; border: 1px solid var(--border); }
.m-get { color: var(--info-text); background: var(--info-bg); border-color: var(--info-border); }
.m-post { color: var(--ok-text); background: var(--ok-bg); border-color: var(--ok-border); }
.m-put { color: var(--warn-text); background: var(--warn-bg); border-color: var(--warn-border); }
.m-delete { color: var(--critical-text); background: var(--critical-bg); border-color: var(--critical-border); }
.detail { display: grid; gap: 16px; min-width: 0; }
.sig { margin: 0 0 6px; display: flex; gap: 8px; align-items: center; flex-wrap: wrap; word-break: break-all; }
.sum { margin: 0 0 8px; font-size: var(--fs-lg); }
.meta { display: flex; gap: 8px; flex-wrap: wrap; margin: 0 0 6px; }
.tag { font-size: var(--fs-xs); border: 1px solid var(--border); border-radius: 999px; padding: 1px 8px; color: var(--text-2); }
.params { width: 100%; border-collapse: collapse; font-size: var(--fs-sm); }
.params th { text-align: left; background: var(--surface-2); padding: 6px 12px; font-weight: var(--fw-medium); color: var(--text-2); }
.params td { padding: 6px 12px; border-top: 1px solid var(--border); vertical-align: top; }
.req { margin-left: 6px; font-size: var(--fs-xs); color: var(--warn-text); }
.two { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 16px; }
.errs { margin-top: 10px; }
.errs ul { margin: 6px 0 0; padding-left: 18px; font-size: var(--fs-sm); }
.form { display: grid; gap: 10px; }
.row { display: grid; grid-template-columns: 140px minmax(0, 1fr); gap: 8px; align-items: center; }
.row.col { grid-template-columns: 1fr; }
.body { min-height: 140px; resize: vertical; }
.confirm { display: flex; gap: 8px; align-items: center; font-size: var(--fs-sm); color: var(--warn-text); }
.sendrow { display: flex; gap: 10px; align-items: center; }
.out { background: var(--surface-2); border: 1px solid var(--border); border-radius: var(--r); padding: 10px; max-height: 420px; overflow: auto; font-size: var(--fs-sm); margin: 0; white-space: pre-wrap; word-break: break-word; }
.good { color: var(--ok-text); }
.bad { color: var(--critical-text); }
.muted { color: var(--text-muted); }
.small { font-size: var(--fs-sm); }
.panel-head { display: flex; gap: 10px; align-items: baseline; flex-wrap: wrap; }
@media (max-width: 1000px) { .layout { grid-template-columns: minmax(0, 1fr); } .side { position: static; max-height: 360px; } }
@media (max-width: 560px) { .row { grid-template-columns: 1fr; } }
</style>
